from pathlib import Path
import hashlib,json,collections
R=Path(__file__).resolve().parents[1]
audit=json.loads((R/'AUDIT_V25.json').read_text())
audit.update(version='26.0.0',baseVersion='25.0.0',date='2026-10-07',baseArchiveSha256=hashlib.sha256(Path('/mnt/data/DIVA_PULSE_V25_VISAGES_ARCHIVES_COMPLET.zip').read_bytes()).hexdigest(),testedHtmlSha256=hashlib.sha256((R/'index.html').read_bytes()).hexdigest(),scope='Comparaison acoustique locale de versions réencodées, copie volontaire en variantes avec offset accepté, récupération séparée des brouillons faciaux et guides refusés, archives portables remappées, interface mobile. Le runtime physique, le catalogue en ligne et le moteur musical ne sont pas remplacés. Pas de compatibilité universelle ni de persistance native certifiée.')
for item in audit['findings']+audit['newFindings']:
 item['previousStatusV25']=item['status']
 item['validationV26']='Preuves historiques conservées. RAPPORT_V26.md indique les suites réexécutées sur le HTML V26 ; les anciens résultats ne constituent pas de nouveaux tests.'
def change(id,**fields):
 for f in audit['findings']+audit['newFindings']:
  if f['id']==id:f.update(fields);return
 raise ValueError(id)
change('A29',status='Avancé, candidats acoustiques locaux; validation en corpus réel ouverte',action='Index spectral/énergie du PCM, propositions après import réencodé, offset ±2 s estimé par pas de 50 ms, contrôle en quatre portions. La copie demande sélection, écoute et confirmation ; nouveaux identifiants et provenance non vérifiée, sans écraser aucune source. Les WAV/MP3 du diagnostic sont reconnus, une autre composition de même BPM est refusée. Aucune preuve d’identité universelle ou recherche en ligne.',evidence='src/audio-match.js ; src/v26-app.js ; tests/v26.test.cjs ; qa/v26/acoustic-fixtures-results.json ; qa/v26/features/browser-final.json',validationV26='Réencodage MP3 réel, gain, polarité, stéréo opposée, décalage ±0,5 s, différence de composition, silence, limites, refus d’écriture et opt-out testés. Pas de mesure de précision/rappel sur une discothèque représentative.')
change('A21',status='Ouvert',action='Physique Bullet, joints et corps souples toujours absents. Une tentative de récupération de la dépendance a échoué dans cette session ; aucun faux moteur, binaire incomplet ou CDN n’est intégré. Les tests existants ne deviennent pas des preuves de physique.',validationV26='Aucune nouvelle simulation physique livrée ou certifiée.')
change('V25-05',status='Avancé, récupération locale et portable; durabilité native non validée',action='Un brouillon facial validé est conservé séparément, avec sa nouvelle voix guide. À la réouverture, reprise explicite ou abandon sans changer la scène. Une publication atomique du visage marque la récupération traitée. Les deux formats de sauvegarde transportent les derniers brouillons et voix guides, même si toutes les écritures sont refusées ; restauration remappée en copies.',evidence='src/face-drafts.js ; src/v26-app.js ; src/v25-app.js ; src/enhancements.js ; qa/v26/features/browser-final.json',validationV26='Fermeture/réouverture du panneau, reprise volontaire, refus d’écriture, guide uniquement en mémoire, export binaire de secours, restauration, publication et abandon contrôlés. Le document est TEMPORAIRE, donc pas de test après fermeture réelle du navigateur.')
change('A20',action='Diagnostic non destructif de bibliothèque conservé. Il signale aussi les descripteurs acoustiques invalides et indique que les copies acoustiques ne sont pas des identités vérifiées.',evidence='src/quality.js ; tests/v26.test.cjs ; tests/v26_regression_v23_browser.py')
change('A40',status='Dépôt V26 à vérifier par reçu séparé',action='Créer un dossier V26 distinct dans le dossier Drive existant, conserver les versions précédentes, envoyer les livrables et relire noms/tailles. La présence dans Drive ne synchronise pas le jeu et ne le publie pas. Voir reçu de dépôt pour les résultats réels, pas cette intention.',evidence='DIVA_PULSE_V26_DEPOT_DRIVE.json (produit seulement après les retours du connecteur)')
audit['newFindings'] += [
 {'id':'V26-01','priority':'P1','area':'Intégrité des partitions','status':'Ajouté et testé','title':'Une ressemblance acoustique ne doit pas remplacer une identité binaire','action':'Scores clairement non probabilistes, aucun niveau précoché, confirmation du timing obligatoire, variantes ajoutées sans écraser les cinq niveaux courants, limite de durée/offset et provenance identityVerified:false. Échec d’écriture atomique sans insertion partielle.','evidence':'src/audio-match.js ; src/v26-app.js ; tests/v26.test.cjs ; qa/v26/features/browser-final.json'},
 {'id':'V26-02','priority':'P1','area':'Sauvegarde','status':'Corrigé et testé','title':'La nouvelle voix guide refusée devait rester dans l’export de secours','action':'Une ressource de voix refusée est gardée avec le dernier brouillon en mémoire. L’export l’inclut sans demander de nouvelles écritures. La restauration réassocie propriétaire et guide avant de proposer une récupération explicite. Un propriétaire ou guide absent est refusé.','evidence':'src/enhancements.js ; src/face-drafts.js ; src/v26-app.js ; qa/v26/features/browser-final.json'},
 {'id':'V26-03','priority':'P2','area':'Interface','status':'Corrigé et testé','title':'Les longues actions du panneau acoustique débordaient en portrait','action':'Largeur du contenu de modale bornée, retours à la ligne des actions et sélecteurs en lignes lisibles. Contrôle de scrollWidth/clientWidth et capture à 390×844, après correction d’un débordement détecté visuellement.','evidence':'src/v26.css ; qa/v26/features/02-mobile-candidates.png ; qa/v26/features/browser-final.json'}
]
audit['statusCounts']=dict(collections.Counter(f['status'] for f in audit['findings']+audit['newFindings']))
(R/'AUDIT_V26.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n')
items=audit['findings']+audit['newFindings']
parts=['# DIVA PULSE V26 — Audit actualisé','',f'**{len(items)} constats suivis**, dont les 48 précédents. Version 26.0.0, base V25 contrôlée.','',audit['scope'],'','Les états distinguent les fonctions implémentées, les preuves exécutées et les validations encore manquantes. Les versions historiques et leurs rapports restent conservés. Un test automatisé ne certifie ni un résultat musical humain, ni tous les packs MMD, ni un appareil physique.','', '## Avancées de cette passe','', 'Reconnaissance locale en candidats pour les audios réencodés ; aucune fusion automatique. Récupération explicite des brouillons faciaux et de leurs voix guides, même après refus d’écriture. Archives remappées, préférence désactivable et panneau mobile corrigé. Aucun moteur Bullet livré.','', '## Registre complet','']
for f in items:
 parts += [f"### {f['id']} — {f['title']}",f"**Domaine :** {f.get('area','')} · **État :** {f['status']}",'']
 if f.get('observation'):parts += [f['observation'],'']
 parts += [f.get('action',''),' ',f"**Preuves :** `{f.get('evidence','Voir rapport')}`",'',f.get('validationV26','Contrôle ajouté dans la passe V26 ; voir les preuves ci-dessus.'),'']
parts += ['## Dépôt et portée de la livraison','','Le reçu Drive est produit séparément à partir des retours réels de transfert et de la relecture du dossier. Cet audit n’affirme pas qu’un transfert a réussi avant sa vérification. Aucun partage public ni déploiement n’est demandé.','',f"**SHA-256 du HTML testé :** `{audit['testedHtmlSha256']}`",'']
(R/'AUDIT_V26.md').write_text('\n'.join(parts),encoding='utf-8')
print(len(items),'findings; final HTML',audit['testedHtmlSha256'])
